# /// script
# requires-python = ">=3.10"
# dependencies = ["simplecadapi"]
#
# [tool.simplecadapi]
# id = "model"
# ///
import marimo

app = marimo.App()

with app.setup:
    import simplecadapi as scad
    from simplecadapi import ql
    import math


@app.cell
def _():
    # ---- params ----
    base_l = scad.var("base_l", 60, unit="mm")
    hole_d = scad.var("hole_d", 10, unit="mm")
    tilt_deg = scad.var("tilt_deg", 65, unit="deg")
    bolt_n = 6
    return base_l, hole_d, tilt_deg, bolt_n


@app.cell
def _(base_l):
    # ---- feature: base (build) ----
    base = scad.make_box_rsolid(width=base_l, height=36, depth=8, bottom_face_center=(0, 0, 0))
    return (base,)


@app.cell
def _(base, hole_d):
    # ---- feature: drill (subtract) ----
    _tool = scad.make_cylinder_rsolid(radius=hole_d / 2, height=10, bottom_face_center=(0, 0, -1))
    drill = scad.cut_rsolid(base, _tool)
    return (drill,)


@app.cell
def _(drill):
    model = scad.Part(part_id="model", body=drill)
    return (model,)


if __name__ == "__main__":
    app.run()

